/// <summary>
/// PricingAttribute of table <c>InventDim</c> field ConfigId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventDimConfigId extends UPSPricingAttributeInventDim implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, ConfigId);
}

public Set getAllowedValues()
{
    var       ret = new Set(Types::String);
    InventDim inventDim;

    while select inventDim
        group by ConfigId
    {
        if (! ret.in(inventDim.ConfigId))
        {
            ret.add(inventDim.ConfigId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, ConfigId));
    qbr.value(queryValue(_value));
}
